			8'h16: crc32_byte_calc = 32'hf4d4b551;
			8'h15: crc32_byte_calc = 32'h6ddde4eb;
			8'h14: crc32_byte_calc = 32'h1adad47d;
			8'h13: crc32_byte_calc = 32'h84be41de;
			8'h12: crc32_byte_calc = 32'hf3b97148;
			8'h11: crc32_byte_calc = 32'h6ab020f2;
			8'h10: crc32_byte_calc = 32'h1db71064;
			8'h0f: crc32_byte_calc = 32'h90bf1d91;
			8'h0e: crc32_byte_calc = 32'he7b82d07;
			8'h0d: crc32_byte_calc = 32'h7eb17cbd;
			8'h0c: crc32_byte_calc = 32'h09b64c2b;
			8'h0b: crc32_byte_calc = 32'h97d2d988;
			8'h0a: crc32_byte_calc = 32'he0d5e91e;
			8'h09: crc32_byte_calc = 32'h79dcb8a4;
			8'h08: crc32_byte_calc = 32'h0edb8832;
			8'h07: crc32_byte_calc = 32'h9e6495a3;
			8'h06: crc32_byte_calc = 32'he963a535;
			8'h05: crc32_byte_calc = 32'h706af48f;
			8'h04: crc32_byte_calc = 32'h076dc419;
			8'h03: crc32_byte_calc = 32'h990951ba;
			8'h02: crc32_byte_calc = 32'hee0e612c;
			8'h01: crc32_byte_calc = 32'h77073096;
			8'h00: crc32_byte_calc = 32'h00000000;
			default: crc32_byte_calc = 1'sb0;
		endcase
	endfunction
	reg [31:0] crc_d;
	reg [31:0] crc_q;
	wire crc_en;
	wire [31:0] crc_stages [0:BytesPerWord + 0];
	assign crc_en = set_crc_i | data_valid_i;
	assign crc_stages[0] = crc_q;
	genvar _gv_i_4;
	generate
		for (_gv_i_4 = 0; _gv_i_4 < BytesPerWord; _gv_i_4 = _gv_i_4 + 1) begin : g_crc_stages
			localparam i = _gv_i_4;
			assign crc_stages[i + 1] = {8'h00, crc_stages[i][31:8]} ^ crc32_byte_calc(crc_stages[i][7:0] ^ data_i[i * 8+:8]);
		end
	endgenerate
	always @(*) begin
		if (_sv2v_0)
			;
		if (set_crc_i)
			crc_d = ~crc_in_i;
		else
			crc_d = crc_stages[BytesPerWord];
	end
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			crc_q <= 32'hffffffff;
		else if (crc_en)
			crc_q <= crc_d;
	assign crc_out_o = ~crc_q;
	initial _sv2v_0 = 0;
endmodule
module prim_diff_decode (
	clk_i,
	rst_ni,
	diff_pi,
	diff_ni,
	level_o,
	rise_o,
	fall_o,
	event_o,
	sigint_o
);
	reg _sv2v_0;
	parameter [0:0] AsyncOn = 1'b0;
	parameter [31:0] SkewCycles = 1;
	input clk_i;
	input rst_ni;
	input diff_pi;
	input diff_ni;
	output wire level_o;
	output reg rise_o;
	output reg fall_o;
	output wire event_o;
	output reg sigint_o;
	reg level_d;
	reg level_q;
	function automatic integer prim_util_pkg_vbits;
		input integer value;
		prim_util_pkg_vbits = (value == 1 ? 1 : $clog2(value));
	endfunction
	generate
		if (AsyncOn) begin : gen_async
			reg [1:0] state_d;
			reg [1:0] state_q;
			wire diff_p_edge;
			wire diff_n_edge;
			wire diff_check_ok;
			wire level;
			reg diff_pq;
			reg diff_nq;
			wire diff_pd;
			wire diff_nd;
			reg [prim_util_pkg_vbits(SkewCycles + 1) - 1:0] skew_cnt_d;
			reg [prim_util_pkg_vbits(SkewCycles + 1) - 1:0] skew_cnt_q;
			prim_flop_2sync #(
				.Width(1),
				.ResetValue(1'sb0)
			) i_sync_p(
				.clk_i(clk_i),
				.rst_ni(rst_ni),
				.d_i(diff_pi),
				.q_o(diff_pd)
			);
			prim_flop_2sync #(
				.Width(1),
				.ResetValue(1'b1)
			) i_sync_n(
				.clk_i(clk_i),
				.rst_ni(rst_ni),
				.d_i(diff_ni),
				.q_o(diff_nd)
			);
			assign diff_p_edge = diff_pq ^ diff_pd;
			assign diff_n_edge = diff_nq ^ diff_nd;
			assign diff_check_ok = diff_pd ^ diff_nd;
			assign level = diff_pd;
			assign level_o = level_d;
			assign event_o = rise_o | fall_o;
			always @(*) begin : p_diff_fsm
				if (_sv2v_0)
					;
				state_d = state_q;
				level_d = level_q;
				skew_cnt_d = skew_cnt_q;
				rise_o = 1'b0;
				fall_o = 1'b0;
				sigint_o = 1'b0;
				(* full_case, parallel_case *)
				case (state_q)
					2'd0:
						if (diff_check_ok) begin
							level_d = level;
							if (diff_p_edge && diff_n_edge) begin
								if (level)
									rise_o = 1'b1;
								else
									fall_o = 1'b1;
							end
						end
						else if (SkewCycles == 0) begin
							state_d = 2'd2;
							sigint_o = 1'b1;
						end
						else begin
							state_d = 2'd1;
							skew_cnt_d = 1;
						end
					2'd1:
						if (diff_check_ok) begin
							state_d = 2'd0;
							level_d = level;
							skew_cnt_d = 1'sb0;
							if (level)
								rise_o = 1'b1;
							else
								fall_o = 1'b1;
						end
						else if (skew_cnt_q < SkewCycles)
							skew_cnt_d = skew_cnt_q + 1;
						else begin
							state_d = 2'd2;
							sigint_o = 1'b1;
							skew_cnt_d = 1'sb0;
						end
					2'd2: begin
						sigint_o = 1'b1;
						if (diff_check_ok) begin
							state_d = 2'd0;
							sigint_o = 1'b0;
							level_d = level;
							if (level)
								rise_o = 1'b1;
							else
								fall_o = 1'b1;
						end
					end
					default:
						;
				endcase
			end
			always @(posedge clk_i or negedge rst_ni) begin : p_sync_reg
				if (!rst_ni) begin
					state_q <= 2'd0;
					diff_pq <= 1'b0;
					diff_nq <= 1'b1;
					level_q <= 1'b0;
					skew_cnt_q <= 1'sb0;
				end
				else begin
					state_q <= state_d;
					diff_pq <= diff_pd;
					diff_nq <= diff_nd;
					level_q <= level_d;
					skew_cnt_q <= skew_cnt_d;
				end
			end
		end
		else begin : gen_no_async
			reg diff_pq;
			wire diff_pd;
			assign diff_pd = diff_pi;
			wire [1:1] sv2v_tmp_u_xnor2_sigint_out_o;
			always @(*) sigint_o = sv2v_tmp_u_xnor2_sigint_out_o;
			prim_xnor2 #(.Width(1)) u_xnor2_sigint(
				.in0_i(diff_pi),
				.in1_i(diff_ni),
				.out_o(sv2v_tmp_u_xnor2_sigint_out_o)
			);
			assign level_o = (sigint_o ? level_q : diff_pi);
			wire [1:1] sv2v_tmp_AB662;
			assign sv2v_tmp_AB662 = level_o;
			always @(*) level_d = sv2v_tmp_AB662;
			wire [1:1] sv2v_tmp_8926B;
			assign sv2v_tmp_8926B = (~diff_pq & diff_pi) & ~sigint_o;
			always @(*) rise_o = sv2v_tmp_8926B;
			wire [1:1] sv2v_tmp_A5341;
			assign sv2v_tmp_A5341 = (diff_pq & ~diff_pi) & ~sigint_o;
			always @(*) fall_o = sv2v_tmp_A5341;
			assign event_o = rise_o | fall_o;
			always @(posedge clk_i or negedge rst_ni) begin : p_edge_reg
				if (!rst_ni) begin
					diff_pq <= 1'b0;
					level_q <= 1'b0;
				end
				else begin
					diff_pq <= diff_pd;
					level_q <= level_d;
				end
			end
		end
	endgenerate
	initial _sv2v_0 = 0;
endmodule
module prim_diff_encode (
	clk_i,
	rst_ni,
	req_i,
	diff_po,
	diff_no
);
	input wire clk_i;
	input wire rst_ni;
	input wire req_i;
	output wire diff_po;
	output wire diff_no;
	wire req;
	prim_sec_anchor_buf #(.Width(1)) u_prim_buf_in_req(
		.in_i(req_i),
		.out_o(req)
	);
	wire diff_p;
	wire diff_n;
	assign diff_p = req;
	assign diff_n = ~req;
	prim_sec_anchor_buf #(.Width(2)) u_prim_buf_ack(
		.in_i({diff_n, diff_p}),
		.out_o({diff_n_buf, diff_p_buf})
	);
	wire diff_p_buf;
	prim_flop #(
		.Width(1),
		.ResetValue(1'b0)
	) u_diff_p(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.d_i(diff_p_buf),
		.q_o(diff_po)
	);
	wire diff_n_buf;
	prim_flop #(
		.Width(1),
		.ResetValue(1'b1)
	) u_diff_n(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.d_i(diff_n_buf),
		.q_o(diff_no)
	);
endmodule
module prim_diff_to_alert (
	clk_i,
	rst_ni,
	diff_pi,
	diff_ni,
	alert_rx_i,
	alert_tx_o
);
	parameter [0:0] AsyncOn = 1'b1;
	parameter [31:0] SkewCycles = 1;
	parameter [0:0] IsFatal = 1'b1;
	input wire clk_i;
	input wire rst_ni;
	input wire diff_pi;
	input wire diff_ni;
	input wire [3:0] alert_rx_i;
	output wire [1:0] alert_tx_o;
	wire diff_p_sync;
	wire diff_n_sync;
	generate
		if (AsyncOn) begin : gen_async
			prim_flop_2sync #(
				.Width(2),
				.ResetValue(2'b10)
			) u_sync(
				.clk_i(clk_i),
				.rst_ni(rst_ni),
				.d_i({diff_ni, diff_pi}),
				.q_o({diff_n_sync, diff_p_sync})
			);
		end
		else begin : gen_sync
			assign diff_p_sync = diff_pi;
			assign diff_n_sync = diff_ni;
		end
	endgenerate
	wire diff_p_buf;
	wire diff_n_buf;
	prim_sec_anchor_buf #(.Width(2)) u_prim_buf_ack(
		.in_i({diff_n_sync, diff_p_sync}),
		.out_o({diff_n_buf, diff_p_buf})
	);
	wire alert_req;
	assign alert_req = diff_p_buf | ~diff_n_buf;
	prim_alert_sender #(
		.AsyncOn(AsyncOn),
		.SkewCycles(SkewCycles),
		.IsFatal(IsFatal)
	) u_prim_alert_sender(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.alert_test_i(1'b0),
		.alert_req_i(alert_req),
		.alert_ack_o(),
		.alert_state_o(),
		.alert_rx_i(alert_rx_i),
		.alert_tx_o(alert_tx_o)
	);
endmodule
module prim_dom_and_2share (
	clk_i,
	rst_ni,
	a0_i,
	a1_i,
	b0_i,
	b1_i,
	z_valid_i,
	z_i,
	q0_o,
	q1_o,
	prd_o
);
	parameter signed [31:0] DW = 64;
	parameter [0:0] Pipeline = 1'b0;
	input clk_i;
	input rst_ni;
	input [DW - 1:0] a0_i;
	input [DW - 1:0] a1_i;
	input [DW - 1:0] b0_i;
	input [DW - 1:0] b1_i;
	input z_valid_i;
	input [DW - 1:0] z_i;
	output wire [DW - 1:0] q0_o;
	output wire [DW - 1:0] q1_o;
	output wire [DW - 1:0] prd_o;
	wire [DW - 1:0] t0_d;
	wire [DW - 1:0] t0_q;
	wire [DW - 1:0] t1_d;
	wire [DW - 1:0] t1_q;
	wire [DW - 1:0] t_a0b0;
	wire [DW - 1:0] t_a1b1;
	wire [DW - 1:0] t_a0b0_d;
	wire [DW - 1:0] t_a1b1_d;
	wire [DW - 1:0] t_a0b1;
	wire [DW - 1:0] t_a1b0;
	assign t_a0b0_d = a0_i & b0_i;
	assign t_a1b1_d = a1_i & b1_i;
	assign t_a0b1 = a0_i & b1_i;
	assign t_a1b0 = a1_i & b0_i;
	prim_xor2 #(.Width(DW * 2)) u_prim_xor_t01(
		.in0_i({t_a0b1, t_a1b0}),
		.in1_i({z_i, z_i}),
		.out_o({t0_d, t1_d})
	);
	prim_flop_en #(
		.Width(DW * 2),
		.ResetValue(1'sb0)
	) u_prim_flop_t01(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.en_i(z_valid_i),
		.d_i({t0_d, t1_d}),
		.q_o({t0_q, t1_q})
	);
	generate
		if (Pipeline == 1'b1) begin : gen_inner_domain_regs
			wire [DW - 1:0] t_a0b0_q;
			wire [DW - 1:0] t_a1b1_q;
			prim_flop_en #(
				.Width(DW * 2),
				.ResetValue(1'sb0)
			) u_prim_flop_tab01(
				.clk_i(clk_i),
				.rst_ni(rst_ni),
				.en_i(z_valid_i),
				.d_i({t_a0b0_d, t_a1b1_d}),
				.q_o({t_a0b0_q, t_a1b1_q})
			);
			assign t_a0b0 = t_a0b0_q;
			assign t_a1b1 = t_a1b1_q;
		end
		else begin : gen_no_inner_domain_regs
			assign t_a0b0 = t_a0b0_d;
			assign t_a1b1 = t_a1b1_d;
		end
	endgenerate
	prim_xor2 #(.Width(DW * 2)) u_prim_xor_q01(
		.in0_i({t_a0b0, t_a1b1}),
		.in1_i({t0_q, t1_q}),
		.out_o({q0_o, q1_o})
	);
	assign prd_o = t1_q;
endmodule
module prim_double_lfsr (
	clk_i,
	rst_ni,
	seed_en_i,
	seed_i,
	lfsr_en_i,
	entropy_i,
	state_o,
	err_o
);
	parameter LfsrType = "GAL_XOR";
	parameter [31:0] LfsrDw = 32;
	localparam [31:0] LfsrIdxDw = $clog2(LfsrDw);
	parameter [31:0] EntropyDw = 8;
	parameter [31:0] StateOutDw = 8;
	function automatic signed [LfsrDw - 1:0] sv2v_cast_C2EBB_signed;
		input reg signed [LfsrDw - 1:0] inp;
		sv2v_cast_C2EBB_signed = inp;
	endfunction
	parameter [LfsrDw - 1:0] DefaultSeed = sv2v_cast_C2EBB_signed(1);
	parameter [LfsrDw - 1:0] CustomCoeffs = 1'sb0;
	parameter [0:0] StatePermEn = 1'b0;
	parameter [(LfsrDw * LfsrIdxDw) - 1:0] StatePerm = 1'sb0;
	parameter [0:0] MaxLenSVA = 1'b1;
	parameter [0:0] LockupSVA = 1'b1;
	parameter [0:0] ExtSeedSVA = 1'b1;
	parameter [0:0] NonLinearOut = 1'b0;
	parameter [0:0] EnableAlertTriggerSVA = 1;
	input clk_i;
	input rst_ni;
	input seed_en_i;
	input [LfsrDw - 1:0] seed_i;
	input lfsr_en_i;
	input [EntropyDw - 1:0] entropy_i;
	output wire [StateOutDw - 1:0] state_o;
	output wire err_o;
	wire [(2 * LfsrDw) - 1:0] lfsr_state;
	genvar _gv_k_3;
	generate
		for (_gv_k_3 = 0; _gv_k_3 < 2; _gv_k_3 = _gv_k_3 + 1) begin : gen_double_lfsr
			localparam k = _gv_k_3;
			wire lfsr_en_buf;
			wire seed_en_buf;
			wire [EntropyDw - 1:0] entropy_buf;
			wire [LfsrDw - 1:0] seed_buf;
			wire [LfsrDw - 1:0] lfsr_state_unbuf;
			prim_buf #(.Width((EntropyDw + LfsrDw) + 2)) u_prim_buf_input(
				.in_i({seed_en_i, seed_i, lfsr_en_i, entropy_i}),
				.out_o({seed_en_buf, seed_buf, lfsr_en_buf, entropy_buf})
			);
			prim_lfsr #(
				.LfsrType(LfsrType),
				.LfsrDw(LfsrDw),
				.EntropyDw(EntropyDw),
				.StateOutDw(LfsrDw),
				.DefaultSeed(DefaultSeed),
				.CustomCoeffs(CustomCoeffs),
				.StatePermEn(StatePermEn),
				.StatePerm(StatePerm),
				.MaxLenSVA(MaxLenSVA),
				.LockupSVA(LockupSVA),
				.ExtSeedSVA(ExtSeedSVA),
				.NonLinearOut(NonLinearOut)
			) u_prim_lfsr(
				.clk_i(clk_i),
				.rst_ni(rst_ni),
				.seed_en_i(seed_en_buf),
				.seed_i(seed_buf),
				.lfsr_en_i(lfsr_en_buf),
				.entropy_i(entropy_buf),
				.state_o(lfsr_state_unbuf)
			);
			prim_buf #(.Width(LfsrDw)) u_prim_buf_output(
				.in_i(lfsr_state_unbuf),
				.out_o(lfsr_state[k * LfsrDw+:LfsrDw])
			);
		end
	endgenerate
	assign state_o = lfsr_state[StateOutDw - 1-:StateOutDw];
	assign err_o = lfsr_state[0+:LfsrDw] != lfsr_state[LfsrDw+:LfsrDw];
endmodule
module prim_edge_detector (
	clk_i,
	rst_ni,
	d_i,
	q_sync_o,
	q_posedge_pulse_o,
	q_negedge_pulse_o
);
	parameter [31:0] Width = 1;
	parameter [Width - 1:0] ResetValue = 1'sb0;
	parameter [0:0] EnSync = 1'b1;
	input clk_i;
	input rst_ni;
	input [Width - 1:0] d_i;
	output wire [Width - 1:0] q_sync_o;
	output wire [Width - 1:0] q_posedge_pulse_o;
	output wire [Width - 1:0] q_negedge_pulse_o;
	wire [Width - 1:0] q_sync_d;
	reg [Width - 1:0] q_sync_q;
	generate
		if (EnSync) begin : g_sync
			prim_flop_2sync #(
				.Width(Width),
				.ResetValue(ResetValue)
			) u_sync(
				.clk_i(clk_i),
				.rst_ni(rst_ni),
				.d_i(d_i),
				.q_o(q_sync_d)
			);
		end
		else begin : g_nosync
			assign q_sync_d = d_i;
		end
	endgenerate
	assign q_sync_o = q_sync_d;
	always @(posedge clk_i or negedge rst_ni)
		if (!rst_ni)
			q_sync_q <= ResetValue;
		else
			q_sync_q <= q_sync_d;
	assign q_posedge_pulse_o = q_sync_d & ~q_sync_q;
	assign q_negedge_pulse_o = ~q_sync_d & q_sync_q;
endmodule
module prim_esc_receiver (
	clk_i,
	rst_ni,
	esc_req_o,
	esc_rx_o,
	esc_tx_i
);
	reg _sv2v_0;
	parameter signed [31:0] N_ESC_SEV = 4;
	parameter signed [31:0] PING_CNT_DW = 16;
	parameter [31:0] SkewCycles = 1;
	localparam signed [31:0] MarginFactor = 4;
	localparam signed [31:0] NumWaitCounts = 2;
	localparam signed [31:0] NumTimeoutCounts = 2;
	parameter signed [31:0] TimeoutCntDw = ((2 + $clog2(N_ESC_SEV)) + 2) + PING_CNT_DW;
	input clk_i;
	input rst_ni;
	output wire esc_req_o;
	output wire [1:0] esc_rx_o;
	input wire [1:0] esc_tx_i;
	wire esc_level;
	wire esc_p;
	wire esc_n;
	wire sigint_detected;
	prim_buf #(.Width(2)) u_prim_buf_esc(
		.in_i({esc_tx_i[0], esc_tx_i[1]}),
		.out_o({esc_n, esc_p})
	);
	prim_diff_decode #(
		.AsyncOn(1'b0),
		.SkewCycles(SkewCycles)
	) u_decode_esc(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.diff_pi(esc_p),
		.diff_ni(esc_n),
		.level_o(esc_level),
		.rise_o(),
		.fall_o(),
		.event_o(),
		.sigint_o(sigint_detected)
	);
	reg ping_en;
	wire timeout_cnt_error;
	wire timeout_cnt_set;
	wire timeout_cnt_en;
	wire [TimeoutCntDw - 1:0] timeout_cnt;
	assign timeout_cnt_set = ping_en && !(&timeout_cnt);
	assign timeout_cnt_en = timeout_cnt > {TimeoutCntDw {1'sb0}};
	function automatic signed [TimeoutCntDw - 1:0] sv2v_cast_FC2B8_signed;
		input reg signed [TimeoutCntDw - 1:0] inp;
		sv2v_cast_FC2B8_signed = inp;
	endfunction
	prim_count #(
		.Width(TimeoutCntDw),
		.EnableAlertTriggerSVA(0),
		.PossibleActions(4'h2 | 4'h4)
	) u_prim_count(
		.clk_i(clk_i),
		.rst_ni(rst_ni),
		.clr_i(1'b0),
		.set_i(timeout_cnt_set),
		.set_cnt_i(sv2v_cast_FC2B8_signed(1)),
		.incr_en_i(timeout_cnt_en),
		.decr_en_i(1'b0),
		.step_i(sv2v_cast_FC2B8_signed(1)),
		.commit_i(1'b1),
		.cnt_o(timeout_cnt),
		.cnt_after_commit_o(),
		.err_o(timeout_cnt_error)
	);
	reg esc_req;
	wire esc_req_d;
	reg esc_req_q;
	assign esc_req_d = (esc_req || &timeout_cnt) || timeout_cnt_error;
	always @(posedge clk_i or negedge rst_ni)
