							b_wdata_d[(i * 9) + 8] = ~(^b_wdata_i[i * 8+:8]);
							b_wmask_d[(i * 9) + 8] = &b_wmask_i[i * 8+:8];
							a_rerror_d[1] = a_rerror_d[1] | ~(^{a_rdata_sram[i * 9+:8], a_rdata_sram[(i * 9) + 8]});
							b_rerror_d[1] = b_rerror_d[1] | ~(^{b_rdata_sram[i * 9+:8], b_rdata_sram[(i * 9) + 8]});
