				if (!rst_b_ni) begin
					b_req_q <= 1'sb0;
					b_write_q <= 1'sb0;
					b_addr_q <= 1'sb0;
					b_wdata_q <= 1'sb0;
					b_wmask_q <= 1'sb0;
				end
				else begin
					b_req_q <= b_req_d;
					b_write_q <= b_write_d;
					b_addr_q <= b_addr_d;
					b_wdata_q <= b_wdata_d;
					b_wmask_q <= b_wmask_d;
				end
		end
		else begin : gen_dirconnect_input
			wire [1:1] sv2v_tmp_190FC;
			assign sv2v_tmp_190FC = a_req_d;
