			wire [1:1] sv2v_tmp_B2158;
			assign sv2v_tmp_B2158 = a_write_d;
			always @(*) a_write_q = sv2v_tmp_B2158;
			wire [Aw:1] sv2v_tmp_70B4E;
			assign sv2v_tmp_70B4E = a_addr_d;
			always @(*) a_addr_q = sv2v_tmp_70B4E;
			wire [TotalWidth:1] sv2v_tmp_D13F8;
			assign sv2v_tmp_D13F8 = a_wdata_d;
			always @(*) a_wdata_q = sv2v_tmp_D13F8;
			wire [TotalWidth:1] sv2v_tmp_78878;
			assign sv2v_tmp_78878 = a_wmask_d;
