			wire [1:1] sv2v_tmp_8B29C;
			assign sv2v_tmp_8B29C = b_req_d;
			always @(*) b_req_q = sv2v_tmp_8B29C;
			wire [1:1] sv2v_tmp_0EE78;
			assign sv2v_tmp_0EE78 = b_write_d;
			always @(*) b_write_q = sv2v_tmp_0EE78;
			wire [Aw:1] sv2v_tmp_9C7DE;
			assign sv2v_tmp_9C7DE = b_addr_d;
			always @(*) b_addr_q = sv2v_tmp_9C7DE;
			wire [TotalWidth:1] sv2v_tmp_741F8;
			assign sv2v_tmp_741F8 = b_wdata_d;
			always @(*) b_wdata_q = sv2v_tmp_741F8;
			wire [TotalWidth:1] sv2v_tmp_161F8;
			assign sv2v_tmp_161F8 = b_wmask_d;
