			mem_addr_i <= pipeline_addr_b_0;
		else if (pipeline_valid[1])
			mem_addr_i <= pipeline_addr_a_0 + 16'h1000;
		else if (pipeline_valid[4])
			mem_addr_i <= pipeline_addr_a_4;
		else
			mem_addr_i <= 16'h0000;
