		if (!reset_n_i)
			mem_write_i <= 1'b0;
		else if (pipeline_valid[4])
			mem_write_i <= 1'b1;
		else
			mem_write_i <= 1'b0;
	always @(posedge clk_i)
		if ((fft_state == 3'd3) && mem_ready_o) begin
			pipeline_valid[0] <= 1'b1;
			pipeline_addr_a_0 <= addr_a;
