			butterfly_result_imag_a <= butterfly_imag_a + butterfly_imag_b;
			butterfly_temp_real <= butterfly_real_a - butterfly_real_b;
			butterfly_temp_imag <= butterfly_imag_a - butterfly_imag_b;
		end
		else
			pipeline_valid[3] <= 1'b0;
